package com.quickchat.bridge;
import com.google.gson.*;import org.java_websocket.*;import org.java_websocket.handshake.ClientHandshake;import org.java_websocket.server.WebSocketServer;import javax.bluetooth.*;import javax.microedition.io.*;import java.io.*;import java.net.InetSocketAddress;import java.nio.charset.StandardCharsets;import java.util.*;

/** RFCOMM bridge for the browser UI. Requires a BlueCove-compatible Bluetooth stack. */
public class Main {
 static final String UUID="8ce255c0200a11e0ac640800200c9a66";static final int CHUNK=8192;static final Gson G=new Gson();
 static volatile StreamConnection connection;static volatile DataInputStream in;static volatile DataOutputStream out;static volatile WebSocket browser;static volatile boolean reading;
 static long uploadExpected=0,uploadWritten=0,uploadId=-1; static String uploadName="";
 static void emit(JsonObject o){WebSocket w=browser;if(w!=null&&w.isOpen())w.send(G.toJson(o));}static JsonObject event(String e){JsonObject o=new JsonObject();o.addProperty("event",e);return o;}
 static synchronized void packet(int type,byte[] payload)throws IOException{if(out==null)throw new IOException("Not connected");out.writeByte(type);out.writeInt(payload.length);if(payload.length>0)out.write(payload);out.flush();}
 static byte[] readBytes(DataInputStream d,int n)throws IOException{if(n<0||n>100*1024*1024)throw new IOException("Invalid packet length: "+n);byte[] b=new byte[n];d.readFully(b);return b;}
 static void readLoop(){if(reading)return;reading=true;new Thread(()->{String file="";long total=0,got=0;ByteArrayOutputStream buf=new ByteArrayOutputStream();try{while(true){int type=in.readUnsignedByte(),len=in.readInt();byte[] p=readBytes(in,len);switch(type){case 1->{String s=new String(p,StandardCharsets.UTF_8);JsonObject o=event("text");o.addProperty("message",s);emit(o);packet(5,p);}case 2->{if(p.length<8)throw new IOException("Bad FILE_INFO");total=0;for(int i=0;i<8;i++)total=(total<<8)|(p[i]&255L);file=new String(p,8,p.length-8,StandardCharsets.UTF_8);got=0;buf.reset();JsonObject o=event("fileStart");o.addProperty("name",file);o.addProperty("size",total);emit(o);}case 3->{buf.write(p);got+=p.length;JsonObject o=event("fileProgress");o.addProperty("percent",total==0?0:(int)(got*100/total));emit(o);}case 4->{JsonObject o=event("file");o.addProperty("name",file);o.addProperty("data",Base64.getEncoder().encodeToString(buf.toByteArray()));emit(o);buf.reset();}case 5->{JsonObject o=event("ack");o.addProperty("message",new String(p,StandardCharsets.UTF_8));emit(o);}default->System.err.println("Unknown packet type "+type);}}}catch(Exception ex){status("Disconnected: "+ex.getMessage(),false);}finally{reading=false;closeConnection();}} ,"QuickChat-RFCOMM-Reader").start();}
 static void status(String s,boolean c){JsonObject o=event("status");o.addProperty("message",s);o.addProperty("connected",c);emit(o);}static synchronized void closeConnection(){try{if(connection!=null)connection.close();}catch(Exception ignored){}connection=null;in=null;out=null;}
 static void connect(String addr){new Thread(()->{try{closeConnection();String url="btspp://"+addr.replace(":","")+":"+UUID+";authenticate=true;encrypt=false;master=false";connection=(StreamConnection)Connector.open(url);in=new DataInputStream(connection.openInputStream());out=new DataOutputStream(connection.openOutputStream());status("Connected to "+addr,true);readLoop();}catch(Exception e){status("Connect failed: "+e.getMessage(),false);}}).start();}
 static void server(){new Thread(()->{try{LocalDevice.getLocalDevice().setDiscoverable(DiscoveryAgent.GIAC);String url="btspp://localhost:"+UUID+";name=QuickChat;authenticate=true;encrypt=false";StreamConnectionNotifier n=(StreamConnectionNotifier)Connector.open(url);status("Waiting for RFCOMM connection",false);connection=n.acceptAndOpen();in=new DataInputStream(connection.openInputStream());out=new DataOutputStream(connection.openOutputStream());status("Connected",true);readLoop();}catch(Exception e){status("Server error: "+e.getMessage(),false);}}).start();}
 static void scan(){new Thread(()->{try{LocalDevice local=LocalDevice.getLocalDevice();DiscoveryAgent agent=local.getDiscoveryAgent();Vector<RemoteDevice> v=new Vector<>();synchronized(v){agent.startInquiry(DiscoveryAgent.GIAC,new DiscoveryListener(){public void deviceDiscovered(RemoteDevice d,DeviceClass c){v.add(d);}public void inquiryCompleted(int x){synchronized(v){v.notifyAll();}}public void servicesDiscovered(int t,ServiceRecord[] r){}public void serviceSearchCompleted(int t,int r){}});v.wait(12000);}JsonArray a=new JsonArray();for(RemoteDevice d:v){JsonObject x=new JsonObject();x.addProperty("address",d.getBluetoothAddress());try{x.addProperty("name",d.getFriendlyName(false));}catch(Exception e){x.addProperty("name","Bluetooth device");}a.add(x);}JsonObject o=event("devices");o.add("devices",a);emit(o);}catch(Exception e){status("Scan error: "+e.getMessage(),false);}}).start();}
 static void handle(WebSocket w,String raw){browser=w;try{JsonObject j=JsonParser.parseString(raw).getAsJsonObject();String a=j.get("action").getAsString();switch(a){case"scan","paired"->scan();case"server"->server();case"connect"->connect(j.get("address").getAsString());case"disconnect"->{closeConnection();status("Disconnected",false);}case"sendText"->packet(1,j.get("message").getAsString().getBytes(StandardCharsets.UTF_8));case"sendFileStart"->{uploadId=j.get("id").getAsLong();uploadName=j.get("name").getAsString();uploadExpected=j.get("size").getAsLong();uploadWritten=0;byte[] nb=uploadName.getBytes(StandardCharsets.UTF_8),info=new byte[8+nb.length];for(int i=0;i<8;i++)info[i]=(byte)(uploadExpected>>>(56-i*8));System.arraycopy(nb,0,info,8,nb.length);packet(2,info);status("Sending "+uploadName,false);}
 case"sendFileChunk"->{if(j.get("id").getAsLong()!=uploadId)throw new IOException("Unknown upload session");long offset=j.get("offset").getAsLong();if(offset!=uploadWritten)throw new IOException("File chunk out of order");byte[] data=Base64.getDecoder().decode(j.get("data").getAsString());if(data.length>CHUNK||uploadWritten+data.length>uploadExpected)throw new IOException("Invalid file chunk size");packet(3,data);uploadWritten+=data.length;JsonObject p=event("uploadProgress");p.addProperty("percent",uploadExpected==0?100:(int)(uploadWritten*100/uploadExpected));emit(p);}
 case"sendFileEnd"->{if(j.get("id").getAsLong()!=uploadId||uploadWritten!=uploadExpected)throw new IOException("File transfer is incomplete");packet(4,new byte[0]);status("File sent: "+uploadName,true);uploadId=-1;}
 case"sendFile"->{String name=j.get("name").getAsString();byte[] data=Base64.getDecoder().decode(j.get("data").getAsString());byte[] nb=name.getBytes(StandardCharsets.UTF_8),info=new byte[8+nb.length];long z=data.length;for(int i=0;i<8;i++)info[i]=(byte)(z>>>(56-i*8));System.arraycopy(nb,0,info,8,nb.length);packet(2,info);for(int off=0;off<data.length;off+=CHUNK)packet(3,Arrays.copyOfRange(data,off,Math.min(off+CHUNK,data.length)));packet(4,new byte[0]);}default->status("Unknown action: "+a,false);}}catch(Exception e){status("Bridge error: "+e.getMessage(),false);}}
 public static void main(String[] args)throws Exception{WebSocketServer ws=new WebSocketServer(new InetSocketAddress("127.0.0.1",8765)){public void onOpen(WebSocket c,ClientHandshake h){browser=c;status("Bridge ready — select a Bluetooth device",false);}public void onClose(WebSocket c,int code,String reason,boolean remote){}public void onMessage(WebSocket c,String m){handle(c,m);}public void onError(WebSocket c,Exception e){System.err.println(e);}public void onStart(){System.out.println("QuickChat bridge: ws://127.0.0.1:8765");}};ws.start();}
}
